script:
(function () {
  'use strict';
  // Line of credit payoff. Month m (1-based): APR = starting APR + yearly change x floor((m-1)/12),
  // kept between 0 and 100%. Interest = balance at the start of the month x APR / 12 (rounded to
  // the cent); then any draw scheduled for month m, the month's new charges and (every 12th
  // month) the annual fee are added. The payment is that month's interest during the
  // interest-only months, then the fixed monthly payment, capped at what is owed. The line counts
  // as paid off once the balance reaches $0 with no planned draws still to come. The goal payment
  // is the smallest fixed payment (to the cent, found by bisection) that pays off by the goal
  // month under the same draws, charges, fees and interest-only months.
  // Verified (scratchpad tests/b3debt/lc.test.js):
  //   no draws, $10,000 at 9.5%, $400 a month -> 28 months, matching the closed-form annuity
  //   n = -ln(1 - rB/P) / ln(1 + r) = 27.97, interest within $1 of it;
  //   goal payment for 24 months with no draws = $459.15, the closed-form level payment
  //   rB / (1 - (1 + r)^-24) = $459.145 rounded up to the cent;
  //   0% APR with a $3,000 draw in month 6 -> months = ceil(13,000 / 400) = 33, $0 interest;
  //   12 interest-only months leave the balance unchanged and add 12 months of interest at
  //   $79.17 a month; an annual fee and monthly charges add exactly their totals to amounts paid;
  //   a payment below the interest reports "not paid off within 50 years" instead of looping.
  var MAX_MONTHS = 600;
  var money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', minimumFractionDigits: 2, maximumFractionDigits: 2 });
  var monthName = new Intl.DateTimeFormat('en-US', { month: 'short', year: 'numeric' });

  function cents(x) { return Math.round(x * 100) / 100; }

  // p: { balance, apr, change (decimals), draws: {month: amount}, lastDraw, charges, fee, io }
  function simulate(p, payment, maxMonths, keepRows) {
    var bal = p.balance, interest = 0, paid = 0, rows = [];
    var limit = Math.min(maxMonths || MAX_MONTHS, MAX_MONTHS);
    for (var m = 1; m <= limit; m++) {
      var apr = Math.min(Math.max(p.apr + p.change * Math.floor((m - 1) / 12), 0), 1);
      var i = cents(bal * apr / 12);
      var added = (p.draws[m] || 0) + p.charges + (m % 12 === 0 ? p.fee : 0);
      bal += i + added; interest += i;
      var pay = Math.min(m <= p.io ? i : payment, bal);
      bal = cents(bal - pay); paid += pay;
      if (keepRows) rows.push({ added: added, interest: i, payment: pay, balance: bal });
      if (bal <= 0.005 && m >= p.lastDraw) return { paidOff: true, months: m, interest: interest, paid: paid, rows: rows };
    }
    return { paidOff: false, months: limit, interest: interest, paid: paid, rows: rows };
  }

  function goalPayment(p, goal) {
    var total = p.balance + p.charges * goal + p.fee * Math.ceil(goal / 12);
    Object.keys(p.draws).forEach(function (k) { total += p.draws[k]; });
    var hi = (total + 1) * Math.pow(1 + Math.max(p.apr, p.apr + p.change * Math.floor(goal / 12), 0) / 12, goal) + 1;
    if (!simulate(p, hi, goal).paidOff) return NaN;
    var lo = 0;
    for (var k = 0; k < 200 && hi - lo > 0.001; k++) {
      var mid = (lo + hi) / 2;
      if (simulate(p, mid, goal).paidOff) hi = mid; else lo = mid;
    }
    var pay = Math.ceil(hi * 100 - 1e-6) / 100;
    while (pay > 0.01 && simulate(p, pay - 0.01, goal).paidOff) pay = cents(pay - 0.01);
    return pay;
  }

  function duration(months) {
    var y = Math.floor(months / 12), m = months % 12, parts = [];
    if (y) parts.push(y + (y === 1 ? ' year' : ' years'));
    if (m || !y) parts.push(m + (m === 1 ? ' month' : ' months'));
    return parts.join(' ');
  }

  function dateAfter(months) {
    var now = new Date();
    return monthName.format(new Date(now.getFullYear(), now.getMonth() + months, 1));
  }

  function num(id) { var v = document.getElementById(id).value; return v.trim() === '' ? NaN : parseFloat(v); }
  function optNum(id) { var v = document.getElementById(id).value; return v.trim() === '' ? 0 : parseFloat(v); }
  function set(id, text) { document.getElementById(id).textContent = text; }

  function clearBody(id) {
    var body = document.getElementById(id);
    while (body.firstChild) body.removeChild(body.firstChild);
    return body;
  }

  function addRow(body, cells) {
    var tr = document.createElement('tr');
    cells.forEach(function (text) { var td = document.createElement('td'); td.textContent = text; tr.appendChild(td); });
    body.appendChild(tr);
  }

  function fail(message) {
    var error = document.getElementById('lcError');
    error.hidden = false; error.textContent = message;
    ['lcTime', 'lcInterest', 'lcGoalPay', 'lcIoPay'].forEach(function (id) { set(id, '–'); });
    set('lcTimeNote', ''); set('lcGoalNote', '');
    document.getElementById('lcNote').hidden = true;
    clearBody('lcCompare'); clearBody('lcSchedule');
  }

  function update() {
    var balance = num('lcBalance'), apr = num('lcApr'), payment = num('lcPayment'), io = optNum('lcIo'), goal = num('lcGoal'),
        charges = optNum('lcCharges'), fee = optNum('lcFee'), change = optNum('lcRateChange');
    if ([balance, apr, payment].some(isNaN) || balance < 0 || balance > 1e8 || apr < 0 || apr > 100 || payment < 0) {
      fail('Enter a balance of $0 or more, an APR from 0 to 100% and a monthly payment.'); return;
    }
    if (isNaN(io) || io < 0 || io > 240 || io !== Math.floor(io)) { fail('Enter 0 to 240 whole interest-only months.'); return; }
    if ([charges, fee, change].some(isNaN) || charges < 0 || fee < 0 || change < -20 || change > 20) {
      fail('New charges and the annual fee must be $0 or more, and the yearly rate change between -20 and 20 points.'); return;
    }
    var draws = {}, lastDraw = 0, drawTotal = 0;
    for (var d = 1; d <= 3; d++) {
      var amt = optNum('lcDraw' + d);
      if (isNaN(amt) || amt < 0) { fail('Draw amounts must be $0 or more.'); return; }
      if (amt === 0) continue;
      var month = num('lcDrawMonth' + d);
      if (isNaN(month) || month < 1 || month > 600 || month !== Math.floor(month)) { fail('Enter when each draw happens as 1 to 600 whole months from now.'); return; }
      draws[month] = (draws[month] || 0) + amt;
      lastDraw = Math.max(lastDraw, month); drawTotal += amt;
    }
    if (balance === 0 && drawTotal === 0) { fail('Enter a current balance or a planned draw.'); return; }
    var p = { balance: balance, apr: apr / 100, change: change / 100, draws: draws, lastDraw: lastDraw, charges: charges, fee: fee, io: io };
    var error = document.getElementById('lcError');
    error.hidden = true; error.textContent = '';

    var plan = simulate(p, payment, MAX_MONTHS, true);
    set('lcIoPay', money.format(cents(balance * apr / 1200)));
    var note = document.getElementById('lcNote');
    if (plan.paidOff) {
      set('lcTime', duration(plan.months));
      set('lcTimeNote', 'Paid off by ' + dateAfter(plan.months) + '.');
      set('lcInterest', money.format(plan.interest));
      note.hidden = charges === 0;
      if (charges > 0) note.textContent = 'You keep adding ' + money.format(charges) + ' of new charges each month, so after this date you will need to pay them off in full every month to stay at $0.';
    } else {
      set('lcTime', 'Over 50 years');
      set('lcTimeNote', 'Your payment does not keep up with interest and new borrowing.');
      set('lcInterest', '–');
      note.hidden = false;
      note.textContent = 'At this payment the balance is not paid off within 50 years. Try a higher payment, or see the payment needed to meet your goal.';
    }

    var goalPay = NaN, goalOk = !isNaN(goal) && goal >= 1 && goal <= 600 && goal === Math.floor(goal);
    if (!goalOk) { set('lcGoalPay', '–'); set('lcGoalNote', 'Enter a goal of 1 to 600 whole months.'); }
    else if (goal <= io) { set('lcGoalPay', '–'); set('lcGoalNote', 'Your goal must be longer than the interest-only period.'); }
    else if (goal < lastDraw) { set('lcGoalPay', '–'); set('lcGoalNote', 'Your goal is before your last planned draw.'); }
    else {
      goalPay = goalPayment(p, goal);
      set('lcGoalPay', isNaN(goalPay) ? '–' : money.format(goalPay) + '/mo');
      set('lcGoalNote', isNaN(goalPay) ? 'This goal cannot be met with a fixed payment.'
        : 'To be clear by ' + dateAfter(goal) + (io > 0 ? ', after ' + io + ' interest-only months.' : '.'));
    }

    var compare = clearBody('lcCompare');
    function planRow(label, pay, s) {
      addRow(compare, [label, money.format(pay), s.paidOff ? duration(s.months) : 'Over 50 years',
        s.paidOff ? money.format(s.interest) : '–', s.paidOff ? money.format(s.paid) : '–']);
    }
    planRow('Your plan', payment, plan);
    if (!isNaN(goalPay)) planRow('Meet your ' + goal + '-month goal', goalPay, simulate(p, goalPay, MAX_MONTHS, false));
    var ioYear = simulate({ balance: balance, apr: p.apr, change: p.change, draws: {}, lastDraw: 0, charges: 0, fee: 0, io: 12 }, 0, 12, false);
    addRow(compare, ['Interest only', money.format(cents(balance * apr / 1200)), 'Never',
      money.format(ioYear.interest) + ' in the first year', '–']);

    var sched = clearBody('lcSchedule');
    var shown = Math.min(plan.rows.length, 360);
    for (var k = 0; k < shown; k++) {
      var r = plan.rows[k];
      addRow(sched, [String(k + 1) + (k + 1 === io ? ' (interest-only ends)' : ''), dateAfter(k + 1),
        r.added > 0 ? money.format(r.added) : '–', money.format(r.interest), money.format(r.payment), money.format(r.balance)]);
    }
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = document.getElementById('lcForm');
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    update();
  });
})();
